import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CfwCq2QB.js";const r="/dev-go-docs/shots/0.2.3/zh-CN/light/popup-tools.png",m=JSON.parse('{"title":"资源嗅探与批量下载","description":"","frontmatter":{},"headers":[],"relativePath":"features/media-sniffer.md","filePath":"features/media-sniffer.md"}'),l={name:"features/media-sniffer.md"};function s(n,e,d,c,h,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="资源嗅探与批量下载" tabindex="-1">资源嗅探与批量下载 <a class="header-anchor" href="#资源嗅探与批量下载" aria-label="Permalink to &quot;资源嗅探与批量下载&quot;">​</a></h1><p>一句话：嗅探当前标签页的图片、视频、音频资源，按类型筛选、搜索，单个或批量下载。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>打开目标网页，按 <code>Alt+4</code>（或点弹窗「资源」页）：</p><ul><li>自动列出当前标签页加载过的图片、视频、音频；「刷新」重新扫描，「清空」清掉列表</li><li><strong>筛选</strong>：全部 / 图片 / 视频；<strong>搜索</strong>支持名称、域名、类型</li><li>每条资源显示来源（请求抓取 / 页面 DOM）和类型，图片和常见格式视频可以直接预览</li><li>单个下载 / 复制链接 / 打开链接；也可以「下载全部」批量创建下载任务</li></ul><img src="'+r+'" alt="弹窗资源页" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：弹窗「资源」页——类型筛选、搜索与「下载全部」。</em></p><h2 id="流媒体的说明" tabindex="-1">流媒体的说明 <a class="header-anchor" href="#流媒体的说明" aria-label="Permalink to &quot;流媒体的说明&quot;">​</a></h2><p>视频站大多用 HLS / DASH 流媒体（m3u8 / mpd 清单加分片），DevGo 能识别并展示这类资源，但<strong>不提供拼接下载</strong>：</p><ul><li>流清单、流分片直接保存得不到完整视频，DevGo 会明确提示并跳过，避免下载无用文件</li><li>X（Twitter）的视频会拆成独立音频轨 / 视频轨，同样提示需要合并后才是完整视频</li><li>需要完整视频时，复制链接交给 yt-dlp 之类的下载工具更可靠</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>仅支持 <code>http</code> / <code>https</code> 协议的资源下载</li><li>嗅探的是<strong>当前标签页</strong>：切换标签页后列表会跟随新页面，需要保留的先下载</li></ul>',12)])])}const f=a(l,[["render",s]]);export{m as __pageData,f as default};
